package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type SearchRequest struct {
	TenantID  string `json:"tenant_id"`
	Query     string `json:"query"`
	OrderBy   string `json:"order_by"`
	Direction string `json:"direction"`
}

type Product struct {
	ID    int    `json:"id"`
	Name  string `json:"name"`
	Price float64 `json:"price"`
	SKU   string `json:"sku"`
}

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// sanitizeDirection ensures only ASC or DESC
func sanitizeDirection(dir string) string {
	if strings.ToUpper(dir) == "DESC" {
		return "DESC"
	}
	return "ASC"
}

// validateTenant checks tenant header matches body
func validateTenant(r *http.Request, tenantID string) bool {
	headerTenant := r.Header.Get("X-Tenant-ID")
	return headerTenant == tenantID && tenantID != ""
}

func searchProducts(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}

	var req SearchRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "invalid json", http.StatusBadRequest)
		return
	}

	if !validateTenant(r, req.TenantID) {
		http.Error(w, "tenant mismatch", http.StatusForbidden)
		return
	}

	// Build query - order_by is validated against allowed columns
	allowedColumns := map[string]bool{"name": true, "price": true, "sku": true, "id": true}
	orderCol := "id"
	if allowedColumns[strings.ToLower(req.OrderBy)] {
		orderCol = strings.ToLower(req.OrderBy)
	}

	direction := sanitizeDirection(req.Direction)

	// VULNERABLE: query parameter is concatenated directly into SQL
	// The LIKE clause uses user input without parameterization
	sqlQuery := fmt.Sprintf(
		`SELECT id, name, price, sku FROM products WHERE tenant_id = '%s' AND (name ILIKE '%%%s%%' OR sku ILIKE '%%%s%%') ORDER BY %s %s LIMIT 50`,
		req.TenantID, req.Query, req.Query, orderCol, direction,
	)

	rows, err := db.Query(sqlQuery)
	if err != nil {
		log.Printf("query error: %v", err)
		http.Error(w, "internal error", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	var products []Product
	for rows.Next() {
		var p Product
		if err := rows.Scan(&p.ID, &p.Name, &p.Price, &p.SKU); err != nil {
			continue
		}
		products = append(products, p)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(products)
}

func healthCheck(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", http.StatusServiceUnavailable)
		return
	}
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/v1/products/search", searchProducts)
	http.HandleFunc("/health", healthCheck)
	log.Fatal(http.ListenAndServe(":8080", nil))
}
